python3 -c "
import yaml

with open('/tmp/registry_parsed.yaml', 'r') as f:
    registry = yaml.safe_load(f)

# 1. All experiments with status=RUNNING
print('=' * 80)
print('1. EXPERIMENTS WITH status=RUNNING')
print('=' * 80)
running = []
for exp_id, exp in registry.items():
    if isinstance(exp, dict) and exp.get('status') == 'RUNNING':
        running.append((exp_id, exp))

if not running:
    print('None found.')
else:
    for exp_id, exp in running:
        print(f'\n--- {exp_id} ---')
        for k, v in exp.items():
            print(f'  {k}: {v}')
" 2>&1

python3 -c "
import yaml

with open('/tmp/registry_parsed.yaml', 'r') as f:
    registry = yaml.safe_load(f)

# Check what type registry is and its structure
print(f'Type: {type(registry)}')
if isinstance(registry, dict):
    print(f'Top-level keys: {list(registry.keys())[:10]}')
    # Show first entry fully
    for k, v in list(registry.items())[:1]:
        print(f'\nFirst entry key: {k}')
        print(f'First entry type: {type(v)}')
        if isinstance(v, dict):
            for sk, sv in v.items():
                print(f'  {sk}: {repr(sv)[:200]}')
elif isinstance(registry, list):
    print(f'Length: {len(registry)}')
    if len(registry) > 0:
        print(f'First item type: {type(registry[0])}')
        if isinstance(registry[0], dict):
            for k, v in registry[0].items():
                print(f'  {k}: {repr(v)[:200]}')
" 2>&1

